NOTIONS = [
"def|critère|3||[Lin, Mayo Clin Proc 2005]|La paralysie périodique thyrotoxique associe un accès aigu de faiblesse musculaire flasque, surtout proximale et aux membres inférieurs, une hypokaliémie et une thyrotoxicose.",  # N01
"bas|mécanisme|2||[Lin, Mayo Clin Proc 2005]|Les hormones thyroïdiennes et l'activité adrénergique stimulent la pompe Na+/K+-ATPase, qui fait entrer brutalement le potassium dans les cellules sans perte du capital potassique total.",  # N02
"epi|terrain particulier|2||[Lin, Mayo Clin Proc 2005]|Le trouble touche surtout l'homme adulte, en particulier d'origine asiatique, sans antécédent familial de paralysie périodique.",  # N03
"ana|symptôme|1||[Lin, Mayo Clin Proc 2005 ; avis d'expert]|Un repas riche en glucides, le repos après un effort, le stress ou les corticoïdes déclenchent souvent l'accès, volontiers la nuit ou au réveil.",  # N04
"ana|piège|2||[Lin, Mayo Clin Proc 2005]|Les signes de thyrotoxicose sont souvent discrets ou absents : la paralysie peut révéler l'hyperthyroïdie.",  # N05
"exa|signe|1||[avis d'expert]|L'examen montre des réflexes ostéotendineux diminués ou abolis, une sensibilité et une conscience conservées ; les muscles respiratoires sont rarement atteints.",  # N06
"red|complication|2||[Lin, Mayo Clin Proc 2005 ; avis d'expert]|L'hypokaliémie profonde expose aux troubles du rythme ventriculaires et, plus rarement, à une insuffisance respiratoire : le patient reste sous monitorage ECG.",  # N07
"gold|examen|3||[Lin, Mayo Clin Proc 2005]|Le bilan d'urgence associe kaliémie, TSH et hormones thyroïdiennes libres, phosphatémie, magnésémie, gazométrie, kaliurèse et ECG.",  # N08
"gold|résultat|2||[Lin, Mayo Clin Proc 2005]|L'excrétion urinaire de potassium est basse et l'équilibre acidobasique normal, ce qui signe un transfert et non une perte de potassium.",  # N09
"alt|résultat|1||[Lin, Mayo Clin Proc 2005 ; Manoukian, Arch Intern Med 1999]|Une hypophosphatémie avec hypophosphaturie, une hypercalciurie et une hypomagnésémie modérée accompagnent souvent l'accès.",  # N10
"alt|signe|1||[Lin, Mayo Clin Proc 2005]|L'ECG montre, en plus des signes d'hypokaliémie, une tachycardie sinusale, des QRS amples ou un bloc auriculoventriculaire du premier degré, qui orientent vers la thyrotoxicose.",  # N11
"pos|diagnostic différentiel|2||[Lin, Mayo Clin Proc 2005 ; avis d'expert]|La paralysie périodique hypokaliémique familiale se discute devant une histoire familiale, un début dans l'enfance ou l'adolescence et une fonction thyroïdienne normale.",  # N12
"pos|diagnostic différentiel|1||[Lin, Mayo Clin Proc 2005]|Les pertes rénales ou digestives de potassium (diurétiques, diarrhée, hyperaldostéronisme, acidose tubulaire) donnent une kaliurèse élevée ou un trouble acidobasique.",  # N13
"acu|décision|3||[Lin, Mayo Clin Proc 2005 ; Manoukian, Arch Intern Med 1999]|Le chlorure de potassium à faible dose, avec des kaliémies rapprochées, corrige l'accès ; une recharge massive expose à une hyperkaliémie de rebond.",  # N14
"acu|chiffre|2||[Manoukian, Arch Intern Med 1999]|Une hyperkaliémie de rebond (> 5,0 mmol/l) est survenue dans 42 % des 24 épisodes de la série de Manoukian, car le potassium ressort des cellules à la fin de l'accès.",  # N15
"acu|molécule|2||[Lin, Am J Kidney Dis 2001 ; Lin, Mayo Clin Proc 2005]|Le propranolol, bêtabloquant non sélectif, freine le transfert : 3 mg/kg per os ont corrigé paralysie et hypokaliémie en 2 heures dans une petite série, sans rebond.",  # N16
"acu|piège|1||[Lin, Mayo Clin Proc 2005 ; avis d'expert]|Le potassium se dilue dans du NaCl 0,9 % et non dans du glucose, car l'insuline stimulée par le glucose aggrave le transfert intracellulaire.",  # N17
"chr|décision|2||[Lin, Mayo Clin Proc 2005 ; Manoukian, Arch Intern Med 1999]|Seul le retour à l'euthyroïdie, par traitement de la cause, supprime les accès.",  # N18
"chr|molécule|1||[avis d'expert]|Un bêtabloquant non sélectif se poursuit jusqu'à l'euthyroïdie pour limiter les récidives.",  # N19
"hos|piège|1||[Manoukian, Arch Intern Med 1999]|La phosphatémie se normalise à la fin de l'accès avec ou sans supplément : une recharge en phosphate n'est pas systématique.",  # N20
"pro|pronostic|1||[Manoukian, Arch Intern Med 1999]|Aucun nouvel accès n'est survenu chez les patients de la série de Manoukian une fois l'euthyroïdie atteinte.",  # N21
"sur|examen|1||[Lin, Mayo Clin Proc 2005 ; Manoukian, Arch Intern Med 1999]|La kaliémie se recontrôle à intervalles rapprochés pendant la correction et dans les heures qui suivent, pour dépister le rebond.",  # N22
"fol|décision|1||[avis d'expert]|L'endocrinologue précise la cause de la thyrotoxicose et le patient évite les déclencheurs (repas riches en glucides, alcool, effort intense) jusqu'à l'euthyroïdie.",  # N23
"fol|contexte suisse|1|S|[avis d'expert]|En Suisse, les posologies du propranolol, du thiamazole et du chlorure de potassium se vérifient dans l'AIPS.",  # N24
"epi|piège|1||[Lin, Mayo Clin Proc 2005]|Le trouble s'observe de plus en plus dans les pays occidentaux et chez des patients non asiatiques : il faut l'évoquer chez tout homme jeune avec paralysie hypokaliémique.",  # N25
"def|critère|1||[Magsino, South Med J 2000 ; avis d'expert]|Toute thyrotoxicose peut le déclencher, y compris la prise d'hormones thyroïdiennes exogènes ; la maladie de Basedow en est la cause la plus fréquente.",  # N26
]
